export function t(key: string, langOverride?: SupportedLanguage): string {
  if (!key) return "";
  const lang = langOverride || getLanguage();
  const dict = TRANSLATIONS[lang] || TRANSLATIONS.en;

  // 1. Direct key match in requested language
  if (dict && dict[key]) return dict[key];

  // 2. Case-insensitive key match in requested language
  const lowerKey = key.toLowerCase();
  for (const k in dict) {
    if (k.toLowerCase() === lowerKey) return dict[k];
  }

  // 3. Fallback to English dictionary
  if (TRANSLATIONS.en && TRANSLATIONS.en[key]) return TRANSLATIONS.en[key];
  for (const k in TRANSLATIONS.en) {
    if (k.toLowerCase() === lowerKey) return TRANSLATIONS.en[k];
  }

  // 4. Guaranteed Human Dictionary fallback
  if (HUMAN_FALLBACK_DICTIONARY[key] || HUMAN_FALLBACK_DICTIONARY[lowerKey]) {
    return HUMAN_FALLBACK_DICTIONARY[key] || HUMAN_FALLBACK_DICTIONARY[lowerKey];
  }

  // 5. Ultimate safety net: format key as readable words, never raw snake_case
  return key
    .replace(/^btn_|^label_|^icon_/, "")
    .replace(/_/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase());
}